const body =
  $input.first().json.body || {};

const repo =
  body.repository?.full_name;

if (!repo) {
  throw new Error("Missing repo");
}

const branch =
  (body.ref || "refs/heads/main")
    .replace("refs/heads/", "");

const commits =
  body.commits || [];

const changedFiles = [
  ...commits.flatMap(c => c.added || []),
  ...commits.flatMap(c => c.modified || [])
];

return changedFiles.map(file => ({
  json: {

    repo,

    branch,

    file_path: file

  }
}));

const doc = $input.first().json || {};

const output = {
  ...doc
};

// Safe defaults
if (!output.title || typeof output.title !== "string") {
  output.title = "Untitled";
}

if (!output.description || typeof output.description !== "string") {
  output.description = "";
}

if (!Array.isArray(output.sections)) {
  output.sections = [];
}

// Normalize sections
output.sections = output.sections.map((section, index) => {

  const validSection = {
    ...section
  };

  if (!validSection.type) {
    validSection.type = "text";
  }

  if (!validSection.title) {
    validSection.title =
      `Section ${index + 1}`;
  }

  if (
    validSection.content === undefined ||
    validSection.content === null
  ) {
    validSection.content = "";
  }

  return validSection;
});

return [{
  json: {

    ...output,

    metadata:
      output.metadata || {},

    architecture:
      output.architecture || {}

  }
}];

