const metadata = $input.first().json;
const code = $("Code Cleaner").item.json.code || "";

const text = (
  String(metadata.title || "") +
  " " +
  String(metadata.description || "") +
  " " +
  String(metadata.summary || "") +
  " " +
  String(code)
).toLowerCase();

let systemType = "Software Platform";
let detectedPatterns = [];
let businessValue = [];
let scalabilityNotes = [];
let mermaidDiagram = "";

if (
  text.includes("langchain") ||
  text.includes("langgraph") ||
  text.includes("llm") ||
  text.includes("agent") ||
  text.includes("tensorflow") ||
  text.includes("openai")
) {

  systemType = "AI/ML Platform";

  detectedPatterns.push(
    "Agent-based workflow",
    "Inference pipeline",
    "Model orchestration"
  );

  businessValue.push(
    "AI-powered automation",
    "Decision intelligence"
  );

  scalabilityNotes.push(
    "Model serving scalability",
    "Async task execution"
  );

  mermaidDiagram = `
graph TD
A[User Input] --> B[AI Pipeline]
B --> C[LLM Processing]
C --> D[Response Generation]
`;

} else if (
  text.includes("cart") ||
  text.includes("payment") ||
  text.includes("checkout") ||
  text.includes("order")
) {

  systemType = "E-Commerce Platform";

  detectedPatterns.push(
    "Microservice architecture",
    "Payment workflow"
  );

  businessValue.push(
    "Online transactions",
    "Order automation"
  );

  scalabilityNotes.push(
    "Inventory scaling",
    "High concurrent users"
  );

  mermaidDiagram = `
graph TD
A[Customer] --> B[Frontend Store]
B --> C[Order Service]
C --> D[Payment Gateway]
D --> E[Inventory System]
`;

} else if (
  text.includes("chat") ||
  text.includes("message") ||
  text.includes("socket") ||
  text.includes("conversation")
) {

  systemType = "Real-time Communication Platform";

  detectedPatterns.push(
    "WebSocket communication",
    "Event-driven architecture"
  );

  businessValue.push(
    "Real-time messaging",
    "User collaboration"
  );

  scalabilityNotes.push(
    "Concurrent socket handling",
    "Low latency communication"
  );

  mermaidDiagram = `
graph TD
A[Client] --> B[WebSocket Server]
B --> C[Message Broker]
C --> D[Database]
`;

} else {

  systemType = "General Software Platform";

  detectedPatterns.push(
    "Layered architecture"
  );

  businessValue.push(
    "Business process automation"
  );

  scalabilityNotes.push(
    "Horizontally scalable services"
  );

  mermaidDiagram = `
graph TD
A[Frontend] --> B[Backend API]
B --> C[Database]
`;
}

const architecture = {
  systemType,
  detectedPatterns,
  businessValue,
  scalabilityNotes,
  mermaidDiagram
};

// Preserve top-level fields (file_path, repo, branch, slug, doc_path, section_id)
// that were on the incoming item, so they survive into create-mode downstream
// (Prepare Documentation Prompt / Save To Supabase) instead of being dropped.
return [
  {
    json: {
      ...metadata,
      metadata,
      architecture,
      code
    }
  }
];

const httpResponse = $input.first().json;

function safeGet(nodeName) {
  try {
