// HTTP Request nodes (Fetch GitHub File) only output the response body --
// file_path/repo/branch from the original trigger item do NOT carry through
// automatically, so they must be re-fetched from whichever trigger path ran.
const upstream = safeGet("Validate Input") || safeGet("Validate PR Merge Input") || {};

return [{
  json: {
    code: httpResponse.data,
    file_path: upstream.file_path,
    repo: upstream.repo,
