const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || response.message?.content || response.output || response.text || "";

if (!raw) {
  throw new Error("AI response empty");
}

// 1. Strip markdown code fences safely
let cleaned = raw
  .replace(/\`\`\`json/gi, "")
  .replace(/\`\`\`/g, "")
  .trim();

// 2. Find the first '{'
const start = cleaned.indexOf("{");
if (start === -1) {
  throw new Error("No JSON object found in response");
}

// 3. Extract exactly one balanced JSON object (ignores trailing garbage or multiple objects)
let depth = 0;
let inString = false;
let escapeNext = false;
let end = -1;

for (let i = start; i < cleaned.length; i++) {
  const char = cleaned[i];

  if (inString) {
    if (escapeNext) {
      escapeNext = false;
    } else if (char === "\\") {
      escapeNext = true;
    } else if (char === '"') {
      inString = false;
    }
  } else {
    if (char === '"') {
      inString = true;
    } else if (char === "{") {
      depth++;
    } else if (char === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break; // Stop exactly at the matching closing brace
      }
    }
  }
}

if (end === -1) {
  throw new Error("JSON object is incomplete or unbalanced");
}

cleaned = cleaned.slice(start, end + 1);

// Safely remove corrupted control characters that break JSON.parse
cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");


// Safely escape newlines inside string values so JSON.parse doesn't crash
cleaned = cleaned.replace(/"(?:[^"\\]|\\.)*"/g, function(match) {
  return match
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t")
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");
});

// Fix trailing commas in JSON
cleaned = cleaned.replace(/,\s*([\}\]])/g, '$1');

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error("Failed to parse AI JSON: " + err.message + " | Snippet: " + cleaned.substring(0, 100));
}

return [{
  json: {
    ...$("Metadata Extractor").item.json,
    ...parsed
  }
}];

// 1. Preserve previous workflow state
