return items.map(item => {
  const input = item.json;

  return {
    json: {
      file_path: input.file_path,
      repo: input.repo,
      branch: input.branch,
      slug: input.slug,
      doc_path: input.doc_path,
      section_id: input.section_id,
      mode: input.mode,
      existingDoc: input.existingDoc,

      code: input.code,
      prompt,

      metadata: {
        ...input
      }
    }
  };
});

const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || response.message?.content || response.output || response.text || "";

const prev = $("Prepare Documentation Prompt").item?.json || $("Generate Update Prompt").item?.json || {};

function parseFailure(reason) {
  return [{
    json: {
      ...prev,
      isError: true,
      title: "Documentation Parsing Failed",
      description: reason,
      sections: [{
        type: "text",
        title: "Parsing Error",
        content: "The AI response could not be turned into valid documentation.\n\n" + reason
      }]
    }
  }];
}

if (!raw) {
  return parseFailure("AI response was empty.");
}

let cleaned = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const start = cleaned.indexOf("{");
if (start === -1) {
  return parseFailure("No JSON object found in the AI response.");
}

let depth = 0;
let inString = false;
let escapeNext = false;
let end = -1;

for (let i = start; i < cleaned.length; i++) {
  const char = cleaned[i];
  if (inString) {
    if (escapeNext) {
      escapeNext = false;
    } else if (char === "\\") {
      escapeNext = true;
    } else if (char === '"') {
      inString = false;
    }
  } else {
    if (char === '"') {
      inString = true;
    } else if (char === "{") {
      depth++;
    } else if (char === "}") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
}

if (end === -1) {
  return parseFailure("The AI response's JSON object was incomplete or unbalanced.");
}

cleaned = cleaned.slice(start, end + 1);
cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");
cleaned = cleaned.replace(/"(?:[^"\\]|\\.)*"/g, function (match) {
  return match
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t")
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, "");
});
cleaned = cleaned.replace(/,\s*([\}\]])/g, "$1");

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return parseFailure(
    "Failed to parse AI JSON: " + err.message + " | Snippet: " + cleaned.substring(0, 100)
  );
}

// --- SURGICAL MERGE LOGIC ---
if (prev && prev.mode === "update" && prev.existingDoc) {
  const oldDoc = prev.existingDoc;

  // Deterministic skip — JavaScript decided, ignore LLM response
  if (prev.preSkip === true) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: oldDoc.sections || []
      }
    }];
  }

  // LLM decided to skip
  if (parsed.skip === true) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: oldDoc.sections || []
      }
    }];
  }

  let mergedSections = [...(oldDoc.sections || [])];
  const patches = parsed.updated_sections || [];

  if (patches.length === 0) {
    return [{
      json: {
        ...prev,
        isError: false,
        isSkip: true,
        title: oldDoc.title || prev.title,
        description: oldDoc.description || prev.description,
        sections: mergedSections
      }
    }];
  }

  for (const patch of patches) {
    if (!patch.id) continue;
    const index = mergedSections.findIndex((s) => s.id === patch.id);
    if (index !== -1) {
      const existingSection = mergedSections[index];

      // If the patch has search/replace blocks, apply them to the existing content
      if (Array.isArray(patch.patches) && typeof existingSection.content === 'string') {
        let updatedContent = existingSection.content;
        let patchApplied = false;
        for (const p of patch.patches) {
          if (p.search && updatedContent.includes(p.search)) {
            updatedContent = updatedContent.replace(p.search, p.replace);
            patchApplied = true;
          }
        }
        if (patchApplied) {
          mergedSections[index] = {
            ...existingSection,
            content: updatedContent
          };
        }
      } else if (patch.content !== undefined) {
        // Fallback: replace the whole content
        mergedSections[index] = {
          ...existingSection,
          content: patch.content
        };
      }
    }
  }

  return [{
    json: {
      ...prev,
      isError: false,
      title: oldDoc.title || prev.title,
      description: oldDoc.description || prev.description,
      sections: mergedSections
    }
  }];
}

// Create Mode
return [{
  json: {
    ...prev,
    ...parsed,
    isError: false
  }
}];

const filePath = $json.file_path || "";
const repo = $json.repo || "";

// One doc per REPOSITORY now (not per file) -- slug identifies the whole repo doc.
const repoSlug = repo
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "");

// Stable per-file section id, used to target only this file section inside
// the repo-level doc when merging (see "Generate Update Prompt").
const sectionId = "file-" + filePath
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "");

const docPath = `content/docs/${repoSlug}.mdx`;

return [{
  json: {
    ...$json,
    slug: repoSlug,
    section_id: sectionId,
    doc_path: docPath
  }
}];

// The HTTP node has "Full Response" enabled, so the item is always a single
// object { statusCode, headers, body } — never auto-split by n8n, which
// otherwise happens whenever a top-level JSON array is returned.
const response = $("Check Existing Doc In Supabase").item.json;
const rows = response?.body;

// A successful match returns an array of rows; no match returns an empty array.
const exists = Array.isArray(rows) && rows.length > 0;

return [{
  json: {
    ...$("Find Existing Doc").item.json,
    doc_exists: exists
  }
}];

const existing = $input.first().json;
const newCode = $("Fetch GitHub File").first().json.code;
const find = $("Find Existing Doc").first().json;
const filePath = find.file_path;

const existingDoc = {
  ...existing.content,
  title: existing.title,
  description: existing.description
};
const existingSections = (existing.content && existing.content.sections) || [];

// --- DETERMINISTIC PRE-SKIP ---
// These file types can NEVER contain investor-grade logic changes.
// The LLM is never called for these - saves tokens and avoids false positives.
const lowerPath = (filePath || '').toLowerCase();
const preSkip =
  lowerPath.includes('.github/') ||
  lowerPath.includes('/workflows/') ||
  lowerPath.endsWith('.yml') ||
  lowerPath.endsWith('.yaml') ||
  lowerPath.endsWith('.json') ||
  lowerPath.endsWith('.lock') ||
  lowerPath.endsWith('.md') ||
  lowerPath.endsWith('.gitignore') ||
  lowerPath.includes('/test') ||
  lowerPath.includes('.test.') ||
  lowerPath.includes('.spec.');

// Build section list WITH full content so the model can see exact wording for matching.
const sectionList = existingSections.map(s => {
  let contentStr = '';
  if (typeof s.content === 'string') {
    contentStr = s.content;
  } else if (s.content) {
    contentStr = JSON.stringify(s.content, null, 2);
  }
  return '- id: ' + s.id + ', title: ' + s.title + '\n  CURRENT CONTENT:\n' + contentStr;
}).join('\n\n');

const updateJson = '{ "updated_sections": [ { "id": "<exact-existing-id>", "patches": [ { "search": "<exact paragraph or lines of old logic to replace>", "replace": "<new paragraph or lines of updated logic>" } ] } ] }';

const prompt =
  'You are maintaining investor-grade product documentation for a software system.\n' +
  'This document describes the ENTIRE product. The file below is ONE component of many.\n\n' +

  'YOUR ONLY JOB: Decide if this file change introduces something an INVESTOR or EXECUTIVE would care about.\n\n' +

  '--- SKIP THIS CHANGE (return { "skip": true }) if it is any of the following ---\n' +
  '- A log message, print statement, or debug output change\n' +
  '- A version bump in a comment or string constant (e.g. "VERSION 2.0" -> "VERSION 3.0")\n' +
  '- A code style / formatting / whitespace change\n' +
  '- A refactor with no change in behaviour (renaming a variable, extracting a helper)\n' +
  '- A minor bug fix that doesn\'t change the documented behaviour\n' +
  '- A test, config, or build file change\n' +
  '- Any change where the EXISTING doc sections still accurately describe the behaviour after the change\n\n' +

  '--- UPDATE THE DOC (return updated_sections) if the change is any of the following ---\n' +
  '- A new public API, endpoint, method, or data model that users interact with\n' +
  '- A new integration with an external service (new DB, new API, new protocol)\n' +
  '- A fundamental change to HOW a core pipeline step works (not just what it logs)\n' +
  '- A new feature that changes the product\'s value proposition or capabilities\n' +
  '- A performance or architectural change with real business impact (e.g. adding GZIP compression reducing bandwidth by 70%)\n' +
  '- A security or compliance change\n\n' +

  'STRICT RULES FOR PATCHING:\n' +
  '1. The document is about the WHOLE product. Do NOT rewrite sections to be only about this file.\n' +
  '2. LOCKED SECTIONS — never change these from a single file commit: executive-summary, business-problem, superior-approach, investor-value-proposition, final-conclusion.\n' +
  '3. Maximum 2 sections may be updated. If more than 2 need changes, return { "skip": true } — a major refactor needs human review.\n' +
  '4. Only use section ids exactly as listed below. Do NOT invent new ids.\n' +
  '5. SURGICAL PATCHING ONLY: For text sections, specify "patches" with exact "search" and "replace" fields targeting only the specific lines that changed. Keep all other text identical. For tables/pipelines, specify "content" directly.\n\n' +

  'EXISTING DOCUMENT SECTIONS (with current content):\n' + sectionList + '\n\n' +
  'CHANGED FILE: ' + filePath + '\n\n' +
  'FILE CODE:\n' + (newCode || '').substring(0, 8000) + '\n\n' +
  'Return ONLY one of these JSON formats (no markdown, no explanation):\n' +
  'Nothing investor-relevant changed: { "skip": true }\n' +
  'Investor-relevant change found (max 2 sections): ' + updateJson;

return [{
  json: {
    ...find,
    mode: "update",
    preSkip: preSkip,
    metadata: existing.content?.metadata || {},
    architecture: existing.content?.architecture || {},
    existingDoc: existingDoc,
    prompt
  }
}];

const body = $input.first().json.body || {};

const repo = body.repo;
if (!repo) {
  throw new Error("Missing repo");
}

const branch = body.branch || "main";
const changedFiles = Array.isArray(body.changed_files) ? body.changed_files : [];

return changedFiles.map(file => ({
  json: {
    repo,
    branch,
    file_path: file
  }
}));
